SELECT  FROM postcards


        AND (title LIKE concat('%',#{keyword},'%') OR recipient_input LIKE concat('%',#{keyword},'%'))


        AND postcard_type = #{postcardType}


        AND status = #{status}


ORDER BY created_at DESC, id DESC

