title = #{title}, image_url = #{imageUrl}, recipient_input = #{recipientInput}, is_public = #{isPublic}, postcard_type = #{postcardType}, status = #{status}, review_reason = #{reviewReason}, elements = #{elements}, sender_deleted = #{senderDeleted}, recipient_deleted = #{recipientDeleted},
